    static void collect(View v,List<TextView>out){if(v instanceof TextView)out.add((TextView)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),out);}
    @Test public void launchTabsPromptsAndCount()throws Exception{MainActivity a=start();assertEquals(0,a.selectedTab);for(int i=0;i<3;i++){a.tabs[i].performClick();assertEquals(i,a.selectedTab);}a.tabs[0].performClick();a.plain.setText("中文abc");ShadowLooper.idleMainLooper(500,java.util.concurrent.TimeUnit.MILLISECONDS);assertTrue(a.count.getText().toString().startsWith("5 字符 · 15 /"));ArrayList<TextView>all=new ArrayList<>();for(View p:a.panels)collect(p,all);for(TextView t:all){String s=t.getText().toString();assertFalse(s.contains("V2.0"));assertFalse(s.contains("时间戳"));assertFalse(s.contains("开发者"));}assertEquals(0,a.keys.size());assertEquals(View.GONE,a.progress.getVisibility());a.finish();}
    @Test public void keyVaultCrudBackupAndTamper()throws Exception{MainActivity a=start();String key=Crypto.generate(),second=Crypto.generate();String id=a.vault.add("朋友",key);a.vault.add("其他",second);a.refreshKeys(id);assertEquals(key,a.selectedKey(0));a.vault.rename(id,"朋友A");a.vault.setDefault(id);assertEquals(id,a.vault.defaultId());byte[]stored=KeyVault.read(new FileInputStream(a.vault.file.getBaseFile()),1048576);assertFalse(new String(stored,"UTF-8").contains(key));assertFalse(new String(stored,"UTF-8").contains("朋友A"));KeyVault reopen=new KeyVault(a);assertEquals(key,reopen.find(id).getString("key"));char[]pass="a strong test password 123".toCharArray();byte[]backup=a.vault.backup(pass);a.vault.delete(id);assertEquals(1,a.vault.list().size());assertEquals(1,a.vault.restore(backup,pass));assertEquals(2,a.vault.list().size());assertEquals(0,a.vault.restore(backup,pass));boolean rejected=false;backup[backup.length-1]^=1;try{a.vault.restore(backup,pass);}catch(Exception e){rejected=true;}assertTrue(rejected);assertEquals(2,a.vault.list().size());a.finish();}
    @Test public void dialogValidationAndCancellation()throws Exception{MainActivity a=start();a.keyDialog(false);ShadowLooper.idleMainLooper();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertTrue(d.isShowing());d.getButton(-1).performClick();ShadowLooper.idleMainLooper();AlertDialog error=ShadowAlertDialog.getLatestAlertDialog();assertNotSame(d,error);assertEquals(0,a.vault.list().size());error.dismiss();d.dismiss();a.runJob("test",()->{Thread.sleep(3000);return null;},o->fail("cancelled task completed"));a.requestCancel();long limit=System.currentTimeMillis()+5000;while(a.busy&&System.currentTimeMillis()<limit){Thread.sleep(25);ShadowLooper.idleMainLooper();}assertFalse(a.busy);assertTrue(a.status.getText().toString().contains("取消"));a.finish();}
    @Test public void streamingPngAndImageSelection()throws Exception{MainActivity a=start();int[]p=new int[560*560];Arrays.fill(p,0xff908070);Transport.Image image=new Transport.Image(560,560,p);File file=new File(a.getCacheDir(),"test.png");Images.png(image,file);UriProvider.register(a,file);int[]size=Images.bounds(a,android.net.Uri.parse("content://org.binarypasscode.test/image"));assertArrayEquals(new int[]{560,560},size);a.finish();}
    @Test public void vaultRecovery()throws Exception{
        MainActivity a=start();String key=Crypto.generate(),id=a.vault.add("恢复测试",key);char[]password="test backup password 123".toCharArray();byte[]backup=a.vault.backup(password);File base=a.vault.file.getBaseFile(),bak=new File(base.getPath()+".bak");java.nio.file.Files.move(base.toPath(),bak.toPath());KeyVault recovered=new KeyVault(a);assertEquals(key,recovered.find(id).getString("key"));try(FileOutputStream out=new FileOutputStream(base)){out.write(new byte[]{1,2,3});}MainActivity broken=start();ShadowLooper.idleMainLooper();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertTrue("recovery dialog visible",d.isShowing());d.getButton(-1).performClick();ShadowLooper.idleMainLooper();assertNotNull("rebuilt UI",broken.root);assertEquals(2,broken.selectedTab);assertEquals(0,broken.vault.list().size());assertEquals(1,broken.vault.restore(backup,password));assertTrue("damaged record preserved: "+Arrays.toString(broken.getFilesDir().list()),Arrays.stream(broken.getFilesDir().list()).anyMatch(n->n.startsWith("unreadable-keys-")));broken.finish();a.finish();
    }
    @Test @Config(manifest=Config.NONE,sdk=35,qualifiers="w393dp-h873dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
    public void renderNativeScreensAndLoadPixels()throws Exception{
        MainActivity a=start();String id=a.vault.add("示例联系人",Crypto.generate());a.refreshKeys(id);a.plain.setText("This is a private message. 你好，世界。");ShadowLooper.idleMainLooper(500,java.util.concurrent.TimeUnit.MILLISECONDS);
        for(int tab=0;tab<3;tab++){a.select(tab);if(tab==1){a.resultTime.setText("生成时间（北京时间）：2026-11-03 21:15:42");a.resultText.setText("This is a private message. 你好，世界。");}a.root.measure(View.MeasureSpec.makeMeasureSpec(786,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1746,View.MeasureSpec.EXACTLY));a.root.layout(0,0,786,1746);android.graphics.Bitmap bmp=android.graphics.Bitmap.createBitmap(786,1746,android.graphics.Bitmap.Config.ARGB_8888);a.root.draw(new android.graphics.Canvas(bmp));try(FileOutputStream out=new FileOutputStream("work/bip_android_screen_"+tab+".png")){bmp.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bmp.recycle();}
        int[]pixels=new int[560*560];Arrays.fill(pixels,0xff908070);File file=new File(a.getCacheDir(),"native-test.png");Images.png(new Transport.Image(560,560,pixels),file);UriProvider.register(a,file);Transport.Image image=Images.load(a,android.net.Uri.parse("content://org.binarypasscode.test/image"));assertEquals(560,image.width);assertEquals(0xff908070,image.pixels[0]);assertEquals(0xff908070,image.pixels[image.pixels.length-1]);a.finish();
    }
    static class PickerFiles extends android.content.ContentProvider {
        static Map<String,File> files=new HashMap<>();
        static android.net.Uri add(android.content.Context c,String name,File file){{PickerFiles p=new PickerFiles();android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="org.binarypasscode.files";p.attachInfo(c,info);org.robolectric.shadows.ShadowContentResolver.registerProviderInternal("org.binarypasscode.files",p);}files.put(name,file);return android.net.Uri.parse("content://org.binarypasscode.files/"+name);}
        public boolean onCreate(){return true;}public String getType(android.net.Uri u){return "image/png";}public android.database.Cursor query(android.net.Uri u,String[]p,String s,String[]a,String o){return null;}public android.net.Uri insert(android.net.Uri u,android.content.ContentValues v){return null;}public int delete(android.net.Uri u,String s,String[]a){File f=files.get(u.getLastPathSegment());return f!=null&&f.delete()?1:0;}public int update(android.net.Uri u,android.content.ContentValues v,String s,String[]a){return 0;}public android.os.ParcelFileDescriptor openFile(android.net.Uri u,String mode)throws FileNotFoundException{File f=files.get(u.getLastPathSegment());if(f==null)throw new FileNotFoundException();return android.os.ParcelFileDescriptor.open(f,mode.startsWith("w")?android.os.ParcelFileDescriptor.MODE_WRITE_ONLY|android.os.ParcelFileDescriptor.MODE_CREATE|android.os.ParcelFileDescriptor.MODE_TRUNCATE:android.os.ParcelFileDescriptor.MODE_READ_ONLY);}
    }
    static void waitJob(MainActivity a)throws Exception{long deadline=System.currentTimeMillis()+40000;while(a.busy&&System.currentTimeMillis()<deadline){Thread.sleep(20);ShadowLooper.idleMainLooper();}ShadowLooper.idleMainLooper();assertFalse("worker finished",a.busy);}
    static void capture(MainActivity a,String name)throws Exception{a.root.measure(View.MeasureSpec.makeMeasureSpec(786,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1746,View.MeasureSpec.EXACTLY));a.root.layout(0,0,786,1746);android.graphics.Bitmap bmp=android.graphics.Bitmap.createBitmap(786,1746,android.graphics.Bitmap.Config.ARGB_8888);a.root.draw(new android.graphics.Canvas(bmp));try(FileOutputStream out=new FileOutputStream("work/"+name+".png")){bmp.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bmp.recycle();}
    @Test @Config(manifest=Config.NONE,sdk=35) @GraphicsMode(GraphicsMode.Mode.NATIVE)
    public void exactUnpremultipliedRgbaInput()throws Exception{
        MainActivity a=start();int w=37,h=29;int[]pixels=new int[w*h];Random random=new Random(73);for(int i=0;i<pixels.length;i++)pixels[i]=random.nextInt();File input=new File(a.getCacheDir(),"rgba.png");try(FileOutputStream out=new FileOutputStream(input)){PngWriter.write(new Transport.Image(w,h,pixels),out,true);}android.net.Uri uri=PickerFiles.add(a,"rgba",input);SecretImages.Source loaded=SecretImages.load(a,uri);assertArrayEquals(pixels,loaded.image.pixels);ImagePayload.Prepared png=SecretImages.prepare(a,uri,9000000,true,null);assertTrue(png.png);File reread=new File(a.getCacheDir(),"reread.png");try(FileOutputStream out=new FileOutputStream(reread)){out.write(png.data);}assertArrayEquals(pixels,SecretImages.load(a,PickerFiles.add(a,"reread",reread)).image.pixels);boolean rejected=false;try{SecretImages.prepare(a,uri,200,true,null);}catch(IllegalArgumentException e){rejected=e.getMessage().contains("不会继续缩小");}assertTrue(rejected);a.finish();}
    @Test @Config(manifest=Config.NONE,sdk=35,qualifiers="w393dp-h873dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
    public void imagePickerPngJpegDualPreviewAndSave()throws Exception{
        MainActivity a=start();String id=a.vault.add("示例联系人",Crypto.generate());a.refreshKeys(id);a.messageMode.setSelection(1);a.lossless.setChecked(true);ShadowLooper.idleMainLooper();a.syncMode();assertEquals(View.VISIBLE,a.secretControls.getVisibility());assertEquals(View.GONE,a.plain.getVisibility());assertFalse(a.strength.isEnabled());
        int w=640,h=360;int[]secret=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int p=0;if(x>20&&x<620&&y>20&&y<340)p=0xd2148278;if((x-160)*(x-160)+(y-170)*(y-170)<95*95)p=0xffffc63a;if(x>300&&x<570&&y>90&&y<140)p=0xffffffff;if(x>300&&x<520&&y>180&&y<220)p=0xffb5e5e4;secret[y*w+x]=p;}File secretFile=new File(a.getCacheDir(),"source.png");try(FileOutputStream out=new FileOutputStream(secretFile)){PngWriter.write(new Transport.Image(w,h,secret),out,true);}int[]base=new int[1024*1024];for(int y=0;y<1024;y++)for(int x=0;x<1024;x++)base[y*1024+x]=y>700-Math.abs(512-x)/2?0xff347b60:((x-800)*(x-800)+(y-220)*(y-220)<10000?0xffffd56b:0xff509bdf);File carrier=new File(a.getCacheDir(),"cover.png");try(FileOutputStream out=new FileOutputStream(carrier)){PngWriter.write(new Transport.Image(1024,1024,base),out,false);}
        android.net.Uri secretUri=PickerFiles.add(a,"secret",secretFile),coverUri=PickerFiles.add(a,"cover",carrier);a.onActivityResult(a.OPEN_SECRET,Activity.RESULT_OK,new android.content.Intent().setData(secretUri));waitJob(a);a.onActivityResult(a.OPEN_ENCODE,Activity.RESULT_OK,new android.content.Intent().setData(coverUri));waitJob(a);assertNotNull(a.preview.getDrawable());assertNotNull(a.secretPreview.getDrawable());
        for(boolean png:new boolean[]{true,false}){a.lossless.setChecked(png);a.syncMode();a.encrypt();waitJob(a);assertNotNull("encrypted PNG pending",a.pendingPng);File encoded=new File(a.getCacheDir(),png?"encoded_png.png":"encoded_jpeg.png");android.net.Uri encodedUri=PickerFiles.add(a,png?"encoded_png":"encoded_jpeg",encoded);a.onActivityResult(a.SAVE_PNG,Activity.RESULT_OK,new android.content.Intent().setData(encodedUri));waitJob(a);assertTrue(encoded.length()>0);if(png){a.select(0);capture(a,"bip26_android_encrypt");}android.graphics.drawable.Drawable originalBase=a.preview.getDrawable(),originalSecret=a.secretPreview.getDrawable();android.net.Uri originalBaseUri=a.sourceUri,originalSecretUri=a.secretUri;a.select(1);a.onActivityResult(a.OPEN_DECODE,Activity.RESULT_OK,new android.content.Intent().setData(encodedUri));waitJob(a);a.decrypt();waitJob(a);assertNotNull("image decoded",a.decodedPayload);assertEquals(originalBaseUri,a.sourceUri);assertEquals(originalSecretUri,a.secretUri);assertSame(originalBase,a.preview.getDrawable());assertSame(originalSecret,a.secretPreview.getDrawable());assertEquals(png,a.decodedPayload.png);assertNotNull(a.decodePreview.getDrawable());assertNotNull(a.decodedPreview.getDrawable());assertTrue(a.saveImage.isEnabled());assertFalse(a.copyText.isEnabled());assertTrue(a.resultTime.getText().toString().matches(".*[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}"));assertFalse(a.resultTime.getText().toString().contains("时间戳"));
        File restored=new File(a.getCacheDir(),png?"restored.png":"restored.jpg");android.net.Uri restoredUri=PickerFiles.add(a,png?"restored_png":"restored_jpeg",restored);byte[]expected=a.decodedPayload.data.clone();a.saveDecodedImage();ShadowAlertDialog.getLatestAlertDialog().getButton(AlertDialog.BUTTON_NEUTRAL).performClick();ShadowLooper.idleMainLooper();a.onActivityResult(a.SAVE_IMAGE,Activity.RESULT_OK,new android.content.Intent().setData(restoredUri));waitJob(a);try(FileInputStream in=new FileInputStream(restored)){assertArrayEquals(expected,KeyVault.read(in,9000000));}if(png){assertArrayEquals(secret,SecretImages.load(a,restoredUri).image.pixels);capture(a,"bip26_android_decrypt");}a.clearResult();assertNull(a.decodedPayload);assertNull(a.decodedPreview.getDrawable());assertNotNull(a.decodePreview.getDrawable());}
        a.messageMode.setSelection(0);ShadowLooper.idleMainLooper();a.syncMode();assertEquals(View.VISIBLE,a.plain.getVisibility());assertTrue(a.strength.isEnabled());a.finish();
    }

    @Test public void allImageInputsOfferAlbumAndFilesAndKeyboard()throws Exception{
        MainActivity a=start();
        for(int code:new int[]{a.OPEN_ENCODE,a.OPEN_SECRET,a.OPEN_DECODE}){
            a.openImage(code);AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();
            assertEquals("从相册选择",d.getListView().getAdapter().getItem(0));assertEquals("从文件选择",d.getListView().getAdapter().getItem(1));
            d.getListView().performItemClick(null,1,1);Intent intent=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;
            assertEquals(Intent.ACTION_OPEN_DOCUMENT,intent.getAction());assertEquals(code==a.OPEN_DECODE?"image/png":"image/*",intent.getType());
        }
        for(int code:new int[]{a.OPEN_ENCODE,a.OPEN_SECRET,a.OPEN_DECODE}){String mime=code==a.OPEN_DECODE?"image/png":"image/*";Intent target=new Intent(Intent.ACTION_PICK,android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType(mime);android.content.pm.ResolveInfo resolved=new android.content.pm.ResolveInfo();resolved.activityInfo=new android.content.pm.ActivityInfo();resolved.activityInfo.packageName="gallery.test";resolved.activityInfo.name="Picker";Shadows.shadowOf(a.getPackageManager()).addResolveInfoForIntent(target,resolved);a.pickImage(code,true);assertEquals(Intent.ACTION_PICK,Shadows.shadowOf(a).getNextStartedActivityForResult().intent.getAction());}
        a.plain.requestFocus();a.hideKeyboard();assertFalse(a.plain.hasFocus());
        a.keyDialog(false);AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();ArrayList<TextView>views=new ArrayList<>();collect(dialog.getWindow().getDecorView(),views);
        EditText input=null;for(TextView v:views)if(v instanceof EditText){input=(EditText)v;break;}assertNotNull(input);input.requestFocus();a.hideKeyboard();assertFalse(input.hasFocus());dialog.dismiss();
        File png=new File(a.getCacheDir(),"retry.png");java.nio.file.Files.write(png.toPath(),new byte[]{1,2,3});a.pendingPng=png;
        a.saveToFile(a.SAVE_PNG);assertEquals(Intent.ACTION_CREATE_DOCUMENT,Shadows.shadowOf(a).getNextStartedActivityForResult().intent.getAction());
        a.onActivityResult(a.SAVE_PNG,Activity.RESULT_CANCELED,null);assertTrue(png.exists());assertSame(png,a.pendingPng);
        a.saveToAlbum(a.SAVE_PNG);assertEquals(a.SAVE_PNG,a.albumRequest);a.onRequestPermissionsResult(a.ALBUM_PERMISSION,new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},new int[]{-1});
        AlertDialog denied=ShadowAlertDialog.getLatestAlertDialog();denied.getButton(-1).performClick();ShadowLooper.idleMainLooper();assertEquals(Intent.ACTION_CREATE_DOCUMENT,Shadows.shadowOf(a).getNextStartedActivityForResult().intent.getAction());a.finish();
    }
