    @Test @Config(manifest=Config.NONE,sdk=35)
    public void albumWritesExactBytesPublishesAndRollsBack()throws Exception{
        MainActivity a=start();GalleryProvider provider=new GalleryProvider();android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="media";provider.attachInfo(a,info);ShadowContentResolver.registerProviderInternal("media",provider);
        for(int code:new int[]{a.OPEN_ENCODE,a.OPEN_SECRET,a.OPEN_DECODE}){String mime=code==a.OPEN_DECODE?"image/png":"image/*";Intent target=new Intent(android.provider.MediaStore.ACTION_PICK_IMAGES).setType(mime);android.content.pm.ResolveInfo resolved=new android.content.pm.ResolveInfo();resolved.activityInfo=new android.content.pm.ActivityInfo();resolved.activityInfo.packageName="gallery.test";resolved.activityInfo.name="Picker";Shadows.shadowOf(a.getPackageManager()).addResolveInfoForIntent(target,resolved);a.pickImage(code,true);Intent selected=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;assertEquals(android.provider.MediaStore.ACTION_PICK_IMAGES,selected.getAction());assertEquals(mime,selected.getType());}
        byte[]data=new byte[8193];new Random(79).nextBytes(data);
        for(boolean png:new boolean[]{true,false}){provider.file=new File(a.getCacheDir(),png?"gallery.png":"gallery.jpg");provider.published=false;GalleryImages.save(a,new ByteArrayInputStream(data),png,"test");assertArrayEquals(data,java.nio.file.Files.readAllBytes(provider.file.toPath()));assertTrue(provider.published);assertEquals(png?"image/png":"image/jpeg",provider.inserted.getAsString("mime_type"));assertEquals("Pictures/BinaryImagePasscode",provider.inserted.getAsString("relative_path"));assertEquals(Integer.valueOf(1),provider.inserted.getAsInteger("is_pending"));}
        provider.fail=true;boolean rejected=false;try{GalleryImages.save(a,new ByteArrayInputStream(data),true,"failure");}catch(IOException e){rejected=true;}assertTrue(rejected);assertTrue(provider.deleted);
        provider.fail=false;File cache=new File(a.getCacheDir(),"encrypted.png");java.nio.file.Files.write(cache.toPath(),data);a.pendingPng=cache;a.showSaveOptions(a.SAVE_PNG);ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();ShadowLooper.idleMainLooper();waitJob(a);assertTrue(a.status.getText().toString().contains("已保存到相册"));assertArrayEquals(data,java.nio.file.Files.readAllBytes(provider.file.toPath()));assertTrue(cache.exists());a.finish();
    }

